// エラー実行とトリガー起動失敗の両方に対応してSlack向けメッセージを作る
const d = $input.first().json;
const wf = d.workflow ?? {};
const exec = d.execution ?? {};
const trg = d.trigger ?? {};

const isTriggerError = !exec.id && trg.error != null;
const err = (isTriggerError ? trg.error : exec.error) ?? {};

const now = new Intl.DateTimeFormat('ja-JP', {
  timeZone: 'Asia/Tokyo',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
}).format(new Date());

const lines = [
  '\u{1F6A8} ワークフローがエラーで停止しました',
  '',
  `ワークフロー: ${wf.name ?? '(不明)'}`,
  `発生時刻: ${now}`,
];

const failedNode = exec.lastNodeExecuted ?? err.node?.name;
if (failedNode) lines.push(`失敗ノード: ${failedNode}`);

lines.push('', 'エラー内容:');
lines.push(String(err.message ?? '(詳細不明)').slice(0, 500));

if (exec.url) lines.push('', `実行ログ: ${exec.url}`);
if (isTriggerError) {
  lines.push('', '\u26A0\uFE0F トリガーの起動に失敗しています。ワークフローが動いていない可能性があります。');
}

return [{ json: { text: lines.join('\n') } }];

// このワークフロー自身を、他の全ワークフローのエラー通知先として設定する
// 公開APIのPUTはスキーマ外のキーを拒否する(additionalProperties: false)ため、
// 送信データを許可キーのみに整形する（ワークフロー自動設定と同じ方針）

const allowedSettingKeys = [
  'saveExecutionProgress',
  'saveManualExecutions',
  'saveDataErrorExecution',
  'saveDataSuccessExecution',
  'executionTimeout',
  'errorWorkflow',
  'timezone',
  'executionOrder',
];

// PUT /workflows のノードスキーマが受け付けるトップレベルキー
const allowedNodeKeys = [
  'id', 'name', 'webhookId', 'disabled', 'notesInFlow', 'notes',
  'type', 'typeVersion', 'executeOnce', 'alwaysOutputData',
  'retryOnFail', 'maxTries', 'waitBetweenTries', 'continueOnFail',
  'onError', 'position', 'parameters', 'credentials', 'customTelemetryTags',
];

// AIツールノードで、本来 parameters に入るべきなのにトップレベルに
// 置かれていることがあるキー。parameters へ移して保存し直す。
const parameterKeys = ['descriptionType', 'toolDescription'];

const selfId = $workflow.id;
const targets = [];
const skipped = [];

for (const item of $input.all()) {
  const wf = item.json;
  if (!wf?.id || wf.id === selfId) continue;            // 自分自身には設定しない
  if (wf.isArchived) continue;                           // アーカイブ済みは対象外
  if (wf.settings?.errorWorkflow === selfId) continue;   // 設定済みはスキップ

  const unknownKeys = [];
  const nodes = (wf.nodes ?? []).map((node) => {
    const clean = {};
    const params = { ...(node.parameters ?? {}) };
    for (const [key, value] of Object.entries(node)) {
      if (key === 'parameters') continue;
      if (allowedNodeKeys.includes(key)) {
        clean[key] = value;
      } else if (parameterKeys.includes(key)) {
        if (params[key] === undefined) params[key] = value;
      } else {
        unknownKeys.push(`${node.name}: ${key}`);
      }
    }
    clean.parameters = params;
    return clean;
  });

  if (unknownKeys.length > 0) {
    // APIが拒否する未知のキーを持つワークフローは、壊さないよう更新しない
    skipped.push(`${wf.name}（${unknownKeys.join(', ')}）`);
    continue;
  }

  const settings = {};
  for (const key of allowedSettingKeys) {
    const value = wf.settings?.[key];
    if (value !== undefined) settings[key] = value;
  }
  settings.errorWorkflow = selfId;

  const data = { name: wf.name, nodes, connections: wf.connections ?? {}, settings };
  // 実行記録(staticData)やピン留めデータを消さないよう引き継ぐ
  if (wf.staticData !== undefined && wf.staticData !== null) data.staticData = wf.staticData;
  if (wf.pinData && Object.keys(wf.pinData).length > 0) data.pinData = wf.pinData;

  targets.push({ id: wf.id, data });
}

if (targets.length === 0 && skipped.length > 0) {
  throw new Error(
    'APIが受け付けないフィールドを含むため更新できないワークフローがあります。n8nのUIから手動で設定してください: ' +
    skipped.join(' / ')
  );
}

return targets.map((t) => ({ json: { ...t, skippedNames: skipped } }));

const names = $input.all().map((i) => i.json.name).filter(Boolean);
const skipped = $('エラー通知先を選別').first().json.skippedNames ?? [];

let text =
  '\u2705 エラー通知の設定が完了しました\n\n' +
  `このワークフローをエラー通知先に設定したワークフロー（${names.length}件）:\n` +
  names.map((n) => `・${n}`).join('\n');

if (skipped.length > 0) {
  text +=
    '\n\n\u26A0\uFE0F 以下はAPIが受け付けないフィールドを含むため未設定です。' +
    'n8nのUI（ワークフロー設定 > Error Workflow）から手動で設定してください:\n' +
    skipped.map((n) => `・${n}`).join('\n');
}

return [{ json: { text } }];

